mapper.select:
SELECT P.FINPROD_MARKET_ID finprodMarketId, P.FINPROD_ID finprodId, /** modify by yanya on 20210224 修改为估值基金类型**/
TYPE.TYPE_1 finprodType2, V.VAL_DATE valDate, V.VALUATION valuation, /** modify by yanya on 20210329 更新日期代替创建日期作为导入日**/ NVL(V.UPDATE_TIME, V.CREATE_TIME) importDay, V.PUBLISH_DATE publishDate, CUST.CUSTOMER_NAME fundManager, V.TOTAL_VALUE totalValue, V.REST_NET_VALUE restNetValue, V.DAY7_YEAR_YIELD * 100 day7YearYield FROM FIN_PRODUCT P INNER JOIN FIN_PRODUCT_VALUATION V ON P.FINPROD_MARKET_ID = V.FINPROD_ID and p.FINPROD_TYPE = V.FINPROD_TYPE INNER JOIN FIN_PRODUCT_TYPE TYPE ON P.FINPROD_ID = TYPE.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO CUST ON CUST.CUSTOMER_ID = P.MANAGER AND CUST.IS_ASSTE_MANAGER = #{yes,jdbcType=VARCHAR}
P.FINPROD_TYPE = #{finprodType2,jdbcType=VARCHAR}
AND P.FINPROD_MARKET_ID like concat(concat('%',#{finprodId,jdbcType=VARCHAR}),'%')
AND CUST.CUSTOMER_ID like concat(concat('%',#{fundManager,jdbcType=VARCHAR}),'%')
AND V.VAL_DATE = TO_DATE(#{valDate},'YYYY-MM-DD')

SELECT DISTINCT FIN.FINPROD_MARKET_ID id, FIN.FINPROD_ABBR text FROM FIN_PRODUCT_VALUATION VAL LEFT JOIN FIN_PRODUCT FIN ON FIN.FINPROD_MARKET_ID = VAL.FINPROD_ID WHERE FIN.FINPROD_MARKET_ID LIKE concat(concat('%',#{param,jdbcType=VARCHAR}),'%')
AND ( FIN.FINPROD_MARKET_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) OR FIN.FINPROD_ABBR like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) )
AND FIN.FINPROD_MARKET_ID = #{initValue,jdbcType=VARCHAR}
AND
FIN.FINPROD_TYPE = #{finprodType2,jdbcType=VARCHAR} AND
VAL.FINPROD_TYPE = #{finprodType2,jdbcType=VARCHAR}

SELECT DISTINCT MST.CUSTOMER_ID id, MST.CUSTOMER_NAME text FROM MST_CUSTOMER_INFO MST INNER JOIN FIN_PRODUCT FIN ON FIN.MANAGER = MST.CUSTOMER_ID where MST.CUSTOMER_NAME like concat(concat('%',#{param,jdbcType=VARCHAR}),'%')
AND ( MST.CUSTOMER_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) OR MST.CUSTOMER_NAME like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) )
AND MST.CUSTOMER_ID = #{initValue,jdbcType=VARCHAR}
AND
FIN.FINPROD_TYPE = #{finprodType2,jdbcType=VARCHAR} AND MST.IS_ASSTE_MANAGER = #{yes,jdbcType=VARCHAR}

SELECT FINPROD_MARKET_ID id, FINPROD_ABBR text /*FINPROD_ID hidCode*/ FROM FIN_PRODUCT WHERE FINPROD_MARKET_ID LIKE CONCAT(CONCAT('%',#{param,jdbcType=VARCHAR}),'%')
AND ( FINPROD_MARKET_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) OR FINPROD_ABBR like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) )
AND FINPROD_MARKET_ID = #{initValue,jdbcType=VARCHAR}
AND
FINPROD_TYPE = #{finprodType2,jdbcType=VARCHAR}

SELECT /** modify by yanya on 20210224 修改为估值基金类型**/
T.TYPE_1 FROM FIN_PRODUCT F LEFT JOIN FIN_PRODUCT_TYPE T ON F.FINPROD_ID = T.FINPROD_ID WHERE F.FINPROD_MARKET_ID = #{finprodId,jdbcType=VARCHAR}
AND F.FINPROD_TYPE = #{finprodType2}

SELECT P.FINPROD_MARKET_ID finprodMarketId, P.FINPROD_ID finprodId, /** modify by yanya on 20210224 修改为估值基金类型**/
TYPE.TYPE_1 finprodType2, V.VAL_DATE valDate, V.VALUATION valuation, V.CREATE_TIME importDay, V.PUBLISH_DATE publishDate, CUST.CUSTOMER_NAME fundManager, V.TOTAL_VALUE totalValue, V.REST_NET_VALUE restNetValue, V.DAY7_YEAR_YIELD * 100 day7YearYield FROM FIN_PRODUCT P INNER JOIN FIN_PRODUCT_VALUATION V ON P.FINPROD_MARKET_ID = V.FINPROD_ID and p.FINPROD_TYPE = V.FINPROD_TYPE INNER JOIN FIN_PRODUCT_TYPE TYPE ON P.FINPROD_ID = TYPE.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO CUST ON CUST.CUSTOMER_ID = P.MANAGER AND CUST.IS_ASSTE_MANAGER = #{yes,jdbcType=VARCHAR}
P.FINPROD_TYPE = #{finprodType2,jdbcType=VARCHAR}
AND P.FINPROD_MARKET_ID = #{finprodId,jdbcType=VARCHAR}
AND V.VAL_DATE = TO_DATE(#{valDate},'YYYY-MM-DD')
